#![feature(test)]

extern crate test;
#[cfg(any(test, bench))]
use test::{black_box, Bencher};

use std::{fmt::Display, str::FromStr};

use anyhow::Error;
use core::fmt;
use itertools::Itertools;
use once_cell::sync::Lazy;
use regex::Regex;

mod old {
    use super::*;

    #[derive(Debug, PartialEq)]
    pub struct Snippet {
        pub elements: Vec<SnippetElement>,
    }

    impl Snippet {
        fn extract_elements(
            s: &str,
            pos: usize,
            escs: Vec<&str>,
            loose_escs: Vec<&str>,
        ) -> (Vec<SnippetElement>, usize) {
            let mut elements = Vec::new();
            let mut pos = pos;
            loop {
                if s.len() == pos {
                    break;
                } else if let Some((ele, end)) = Self::extract_tabstop(s, pos) {
                    elements.push(ele);
                    pos = end;
                } else if let Some((ele, end)) = Self::extract_placeholder(s, pos) {
                    elements.push(ele);
                    pos = end;
                } else if let Some((ele, end)) =
                    Self::extract_text(s, pos, escs.clone(), loose_escs.clone())
                {
                    elements.push(ele);
                    pos = end;
                } else {
                    break;
                }
            }
            (elements, pos)
        }

        pub fn extract_tabstop(s: &str, pos: usize) -> Option<(SnippetElement, usize)> {
            for re in &[
                Regex::new(r#"^\$(\d+)"#).unwrap(),
                Regex::new(r#"^\$\{(\d+)\}"#).unwrap(),
            ] {
                if let Some(caps) = re.captures(&s[pos..]) {
                    let end = pos + re.find(&s[pos..])?.end();
                    let m = caps.get(1)?;
                    let n = m.as_str().parse::<usize>().ok()?;
                    return Some((SnippetElement::Tabstop(n), end));
                }
            }

            None
        }

        pub fn extract_placeholder(s: &str, pos: usize) -> Option<(SnippetElement, usize)> {
            let re = Regex::new(r#"^\$\{(\d+):(.*?)\}"#).unwrap();
            let end = pos + re.find(&s[pos..])?.end();

            let caps = re.captures(&s[pos..])?;

            let tab = caps.get(1)?.as_str().parse::<usize>().ok()?;

            let m = caps.get(2)?;
            let content = m.as_str();
            if content.is_empty() {
                return Some((
                    SnippetElement::PlaceHolder(tab, vec![SnippetElement::Text("".to_string())]),
                    end,
                ));
            }
            let (els, pos) =
                Self::extract_elements(s, pos + m.start(), vec!["$", "}", "\\"], vec![]);
            Some((SnippetElement::PlaceHolder(tab, els), pos + 1))
        }

        pub fn extract_text(
            s: &str,
            pos: usize,
            escs: Vec<&str>,
            loose_escs: Vec<&str>,
        ) -> Option<(SnippetElement, usize)> {
            let mut s = &s[pos..];
            let mut ele = "".to_string();
            let mut end = pos;

            while !s.is_empty() {
                if s.len() >= 2 {
                    let esc = &s[..2];
                    let mut new_escs = escs.clone();
                    new_escs.extend_from_slice(&loose_escs);

                    if new_escs
                        .iter()
                        .map(|e| format!("\\{}", e))
                        .any(|x| x == *esc)
                    {
                        ele += &s[1..2];
                        end += 2;
                        s = &s[2..];
                        continue;
                    }
                }
                if escs.contains(&&s[0..1]) {
                    break;
                }
                ele += &s[0..1];
                end += 1;
                s = &s[1..];
            }
            if ele.is_empty() {
                return None;
            }
            Some((SnippetElement::Text(ele), end))
        }

        pub fn text(&self) -> String {
            self.elements.iter().map(|e| e.text()).join("")
        }

        pub fn tabs(&self, pos: usize) -> Vec<(usize, (usize, usize))> {
            Self::elements_tabs(&self.elements, pos)
        }

        pub fn elements_tabs(
            elements: &[SnippetElement],
            start: usize,
        ) -> Vec<(usize, (usize, usize))> {
            let mut tabs = Vec::new();
            let mut pos = start;
            for el in elements {
                match el {
                    SnippetElement::Text(t) => {
                        pos += t.len();
                    }
                    SnippetElement::PlaceHolder(tab, els) => {
                        let placeholder_tabs = Self::elements_tabs(els, pos);
                        let end = pos + els.iter().map(|e| e.len()).sum::<usize>();
                        tabs.push((*tab, (pos, end)));
                        tabs.extend_from_slice(&placeholder_tabs);
                        pos = end;
                    }
                    SnippetElement::Tabstop(tab) => {
                        tabs.push((*tab, (pos, pos)));
                    }
                }
            }
            tabs
        }
    }

    impl FromStr for Snippet {
        type Err = Error;

        fn from_str(s: &str) -> Result<Self, Self::Err> {
            let (elements, _) = Self::extract_elements(s, 0, vec!["$", "\\"], vec!["}"]);
            Ok(Snippet { elements })
        }
    }

    impl Display for Snippet {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            let text = self.elements.iter().map(|e| e.to_string()).join("");
            f.write_str(&text)
        }

## Description
This PR allows for custom selector strategies for icons.

Especially for Fontawesome Pro there are icons which share the exact same words but in a different order ("foo-bar" and "bar-foo" are 2 different icons). This wouldn't work using the default fui logic 

```less
i.icon.foo.bar::before {}
```

Now, it's possible to adjust 3 new variables which would allow different icon class selectors

#### 1. Ordered selector
```less
@iconClassSeparator: " "; // a space separator automatically forces order
// or
@iconForcedOrder: true;
```
results in
```less
i.icon[class*="foo bar"]::before {}
```

####  2. Dashed one word selector
```less
@iconClassSeparator: "-";
```
results in
```less
i.icon.foo-bar::before {}
```

#### 3. Use data attribute instead of classname (this was originally planned as default for 3.0) and optionall use a custom class separator
```less
@iconClassSeparator: "_";
@iconForcedOrder: true;
@iconForcedAttribute: data-icon
```
results in
```less
i.icon[data-icon*="foo_bar"]::before {}
```

I also simplified the generateIcon function so it can be reused for duotone icons (because the only difference is the pseudo selector)

